import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.Cv-B11KK.js";const u=JSON.parse('{"title":"Citation and reference pickers","description":"","frontmatter":{},"headers":[],"relativePath":"citation-reference-pickers.md","filePath":"citation-reference-pickers.md","lastUpdated":1790176871000}'),r={name:"citation-reference-pickers.md"};function n(c,e,s,d,l,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="citation-and-reference-pickers" tabindex="-1">Citation and reference pickers <a class="header-anchor" href="#citation-and-reference-pickers" aria-label="Permalink to &quot;Citation and reference pickers&quot;">​</a></h1><p><strong>Scripts → LaTeX — Insert Citation</strong> searches citation keys, authors, titles, years, and bibliography filenames. Select several results with Shift/Command to insert multiple keys. <strong>Insert Reference</strong> searches saved labels together with their section, equation, figure/table caption, and source location. Existing native TexLab completion and its shortcut remain the quick path.</p><p>Place the cursor inside a key argument or at a normal insertion point:</p><ul><li>Inside <code>\\citet*[see][p. 4]{old}</code>, choosing <code>new</code> produces <code>\\citet*[see][p. 4]{old,new}</code>. Existing keys are kept and duplicates removed. Select a whole key to replace it; a partially selected key is rejected.</li><li>Inside <code>\\eqref{old}</code>, choosing <code>eq:energy</code> replaces only the key. <code>\\ref</code>, <code>\\pageref</code>, <code>\\autoref</code>, <code>\\nameref</code>, and <code>\\vref</code> retain their commands. <code>\\cref</code>/<code>\\Cref</code> retain existing keys and append the chosen label.</li><li>At an ordinary empty insertion point, the commands insert <code>\\cite{...}</code> or <code>\\ref{...}</code>. They do not replace selected prose. An unfinished <code>\\cite{</code> at the end of the buffer can be completed, including its closing brace.</li></ul><p>Common natbib/biblatex single-argument citation commands are recognized: cite/citep/citet/citealp/citealt/citeauthor/citeyear/citeyearpar/parencite/textcite/ autocite/footcite/footfullcite/fullcite/smartcite/supercite/nocite, with a star and up to two optional arguments. Custom commands and multi-command forms such as <code>\\cites</code> are outside the supported insertion scope; use native completion for those commands. The picker does not choose a citation style or change package configuration. Comments and common verbatim regions are excluded.</p><p>Insertion is one undoable editor change. Cancel leaves the document untouched. An already-dirty source buffer is supported: the picker captures its text and selection, then refuses to insert if either changes while the dialog is open. It also rechecks the saved files used to build the results. BBEdit scripting ranges use UTF-16 units; tests include accented text and emoji before the cursor.</p><h2 id="saved-project-data" tabindex="-1">Saved project data <a class="header-anchor" href="#saved-project-data" aria-label="Permalink to &quot;Saved project data&quot;">​</a></h2><p>References reuse the <a href="./project-navigation">project outline index</a>. Citation resources come from literal <code>\\bibliography{one,two}</code> and <code>\\addbibresource[options]{file.bib}</code> declarations in that same root/include graph. Both pickers use saved definitions, including when the insertion buffer is dirty. Save new labels or resource declarations before searching for them. No source, bibliography, or unrelated document is saved automatically.</p><p>Missing resources, malformed bibliography entries, and incomplete project inputs produce a partial-index notice. Valid entries elsewhere remain available. Duplicate citation keys and labels are shown with their locations but cannot be inserted until made unambiguous. Fix the definitions rather than relying on which duplicate a compiler might choose.</p><h2 id="bibliography-parser-and-boundaries" tabindex="-1">Bibliography parser and boundaries <a class="header-anchor" href="#bibliography-parser-and-boundaries" aria-label="Permalink to &quot;Bibliography parser and boundaries&quot;">​</a></h2><p>Citation search runs in the bbtex binary (<code>bbtex citation-picker</code>). Bibliography blocks come from <a href="https://github.com/LouLouLibs/bibtexparser-ml" target="_blank" rel="noreferrer">bibtexparser-ml</a>, vendored in <code>vendor/bibtexparser-ml</code>: an OCaml port of the splitter in <a href="https://github.com/sciunto-org/python-bibtexparser" target="_blank" rel="noreferrer">python-bibtexparser</a> 2.0.1, made for bbtex. Its own repository tests it for identical output against bibtexparser 2.0.1 on edge cases, fuzzed input and real bibliographies.</p><p>The splitter handles entry boundaries, fields, nested braces, quoted values, duplicates, and malformed-block recovery. A bounded value resolver handles <code>@string</code> references and <code>#</code> concatenation across the declared files. Search metadata supports direct <code>crossref</code> and comma-separated <code>xdata</code> inheritance with child values taking precedence; missing/ambiguous parents and cycles are reported. This is metadata fallback for search, not a full implementation of biblatex&#39;s type-specific inheritance rules. TeX markup is retained. Search ignores case and accents: <code>σοφία</code> finds <code>ΣΟΦΊΑ</code>, <code>strasse</code> finds <code>Straße</code>, and <code>garcia</code> finds <code>García</code>. Text is decomposed (Unicode NFD), combining marks are dropped, and the rest is case-folded, using the <a href="https://erratique.ch/software/uucp" target="_blank" rel="noreferrer">uucp</a> and <a href="https://erratique.ch/software/uunf" target="_blank" rel="noreferrer">uunf</a> libraries. Letters without a decomposition keep their identity, so <code>lodz</code> does not find <code>Łódź</code>. UTF-8 (including BOM) bibliography files are supported.</p><p>Each bibliography is limited to 32 MiB, inheritance/string expansion to 32 levels, and a dialog to 300 matches; use a narrower query for larger result sets. The 10,000-entry regression fixture is indexed and searched in about 0.05 seconds locally, excluding dialog interaction.</p><h2 id="setup-and-checks" tabindex="-1">Setup and checks <a class="header-anchor" href="#setup-and-checks" aria-label="Permalink to &quot;Setup and checks&quot;">​</a></h2><p>Development commands are installed by <code>scripts/install-workflow-commands.sh</code>. Release packages include both commands and their helpers. Both searches use the OCaml binary directly; neither needs Python or uv. Errors are logged to <code>~/.local/state/bbtex/picker.log</code>.</p><p><code>dune runtest</code> checks edit planning, the shared index, and citation metadata (string expansion, inheritance, duplicates, recovery and size limits). <code>uv run test/integration/check_pickers.py</code> tests the command-line output and compiles the generated dialogs. Set <code>BBTEX_TEST_NATIVE=1</code> to exercise multi-citation insertion, reference replacement, Undo, cancellation, Unicode ranges, and concurrent buffer/selection changes in disposable BBEdit documents. The automated test substitutes dialog choices; the actual menu interactions are checked separately.</p>',16)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
